ToggleOppositeFlagOfSelectedShapes:
string $selectionList[] = `ls -sl -l -dag -leaf`;
string $selection;
for ($selection in $selectionList) {
    if (`nodeType $selection` == "nurbsSurface") {
        int $op = `getAttr ($selection + ".opposite")`;
        $op = !$op;
        setAttr ($selection + ".opposite") $op;
    }
}

